// Helper to normalize and retrieve media arrays dynamically for any brand
export const getProjectMedia = (brand) => {
  if (!brand) return { images: [], videos: [] };
  const images = brand.images || [];
  const videos = brand.videos || [];
  return { images, videos };
};

